def lru(refs, n):
    rahmen, fehler = [], 0
    for s in refs:
        if s in rahmen:
            rahmen.remove(s)
        else:
            fehler += 1
            if len(rahmen) == n:
                rahmen.pop(0)
        rahmen.append(s)
    return fehler

refs = [1,2,3,1,4,1,5,2,1,4]
print(lru(refs, 3))   # 7
